import{_ as n,a0 as p,w as r,s as d,ao as o,I as l,a1 as i,A as s,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"tmux：适用于重度命令行 Linux 用户的终端复用器 | LCTT x X-CMD","titleTemplate":false,"description":"tmux：适用于重度命令行 Linux 用户的终端复用器 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"tmux：适用于重度命令行 Linux 用户的终端复用器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"tmux：适用于重度命令行 Linux 用户的终端复用器 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User","title":"tmux：适用于重度命令行 Linux 用户的终端复用器","tag":"201901","desc":""},"relativePath":"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User.md","filePath":"[post].md"}'),u={name:"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User.md"};function m(g,e,x,h,c,k){const a=p("Link");return r(),d("div",null,[e[35]||(e[35]=o('<h1 id="tmux-适用于重度命令行-linux-用户的终端复用器" tabindex="-1">tmux：适用于重度命令行 Linux 用户的终端复用器 <a class="header-anchor" href="#tmux-适用于重度命令行-linux-用户的终端复用器" aria-label="Permalink to “tmux：适用于重度命令行 Linux 用户的终端复用器”">​</a></h1><p>tmux 是<ruby>终端复用器<rt>terminal multiplexer</rt></ruby>的缩写，它允许用户在单个窗口中创建或启用多个终端（垂直或水平），当你处理不同的问题时，可以在单个窗口中轻松访问和控制它们。</p><p>它使用客户端-服务器模型，允许在用户之间共享会话，也可以将终端连接到 tmux 会话。我们可以根据需要轻松移动或重新排列虚拟控制台。终端会话可以从一个虚拟控制台自由切换到另一个。</p><p>tmux 依赖于 <code>libevent</code> 和 <code>ncurses</code> 库。tmux 在屏幕底部提供了一个状态行，它显示当前 tmux 会话的有关信息，例如当前窗口编号、窗口名称、用户名、主机名、当前时间和日期。</p><p>启动 tmux 时，它会在一个单独窗口上创建一个新的会话，并将其显示在屏幕上。它允许用户在同一个会话中创建任意数量的窗口。</p><p>许多人说它类似于 <code>screen</code>，但我不这么认为，因为它提供了许多配置选项。</p><p><strong>注意：</strong> <code>Ctrl+b</code> 是 tmux 中的默认命令前缀，因此，要在 tmux 中执行任何操作，你必须先输入该前缀然后输入所需的选项。</p><h3 id="tmux-特性" tabindex="-1">tmux 特性 <a class="header-anchor" href="#tmux-特性" aria-label="Permalink to “tmux 特性”">​</a></h3><ul><li>创建任意数量的窗口</li><li>在一个窗口中创建任意数量的窗格</li><li>它允许垂直和水平分割</li><li>分离并重新连接窗口</li><li>客户端-服务器架构，这允许用户之间共享会话</li><li>tmux 提供许多配置技巧</li></ul><p><strong>建议阅读：</strong></p>',10)),l("ul",null,[l("li",null,[i(a,{href:"https://www.2daygeek.com/tmate-instantly-share-your-terminal-session-to-anyone-in-seconds/"},{default:s(()=>[...e[0]||(e[0]=[t("tmate - 马上与其他人分享你的终端会话",-1)])]),_:1})]),l("li",null,[i(a,{href:"https://www.2daygeek.com/teleconsole-share-terminal-session-instantly-to-anyone-in-seconds/"},{default:s(()=>[...e[1]||(e[1]=[t("Teleconsole - 一个与其他人分享终端会话的工具",-1)])]),_:1})])]),e[36]||(e[36]=l("h3",{id:"如何安装-tmux-命令",tabindex:"-1"},[t("如何安装 tmux 命令 "),l("a",{class:"header-anchor",href:"#如何安装-tmux-命令","aria-label":"Permalink to “如何安装 tmux 命令”"},"​")],-1)),e[37]||(e[37]=l("p",null,"大多数 Linux 系统默认预安装 tmux 命令。如果没有，按照以下步骤安装。",-1)),l("p",null,[e[4]||(e[4]=t("对于 Debian/Ubuntu，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-get-apt-cache-command-examples-manage-packages-debian-ubuntu-systems/"},{default:s(()=>[...e[2]||(e[2]=[t("APT-GET 命令",-1)])]),_:1}),e[5]||(e[5]=t("或 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-command-examples-manage-packages-debian-ubuntu-systems/"},{default:s(()=>[...e[3]||(e[3]=[t("APT 命令",-1)])]),_:1}),e[6]||(e[6]=t("来安装：",-1))]),e[38]||(e[38]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install tmux</span></span></code></pre></div>',1)),l("p",null,[e[8]||(e[8]=t("对于 RHEL/CentOS，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:s(()=>[...e[7]||(e[7]=[t("YUM 命令",-1)])]),_:1}),e[9]||(e[9]=t("来安装：",-1))]),e[39]||(e[39]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tmux</span></span></code></pre></div>',1)),l("p",null,[e[11]||(e[11]=t("对于 Fedora，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/dnf-command-examples-manage-packages-fedora-system/"},{default:s(()=>[...e[10]||(e[10]=[t("DNF 命令",-1)])]),_:1}),e[12]||(e[12]=t("来安装：",-1))]),e[40]||(e[40]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tmux</span></span></code></pre></div>',1)),l("p",null,[e[14]||(e[14]=t("对于 Arch Linux，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/pacman-command-examples-manage-packages-arch-linux-system/"},{default:s(()=>[...e[13]||(e[13]=[t("Pacman 命令",-1)])]),_:1}),e[15]||(e[15]=t("来安装：",-1))]),e[41]||(e[41]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S tmux</span></span></code></pre></div>',1)),l("p",null,[e[17]||(e[17]=t("对于 openSUSE，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/zypper-command-examples-manage-packages-opensuse-system/"},{default:s(()=>[...e[16]||(e[16]=[t("Zypper 命令",-1)])]),_:1}),e[18]||(e[18]=t("来安装：",-1))]),e[42]||(e[42]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper in tmux</span></span></code></pre></div><h3 id="如何使用-tmux" tabindex="-1">如何使用 tmux <a class="header-anchor" href="#如何使用-tmux" aria-label="Permalink to “如何使用 tmux”">​</a></h3><p>在终端上运行以下命令来启动 tmux 会话。启动 tmux 后，它会在一个新窗口中创建新会话，并将使用你的用户账户自动登录到你的默认 shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-1.png" alt=""></p><p>你会得到类似于我们上面的截图。tmux 附带状态栏，显示有关当前会话详细信息、日期、时间等。</p><p>状态栏信息如下：</p><ul><li><code>[0]</code>：它表示由 tmux 服务器创建的会话号。默认情况下，它从 0 开始。</li><li><code>0:bash</code>：表示会话号、命令行提示符（这里的 <code>bash</code> 表示 shell 名称）。</li><li><code>*</code>：这表示该窗口现在处于活动状态。</li><li>主机名：显示服务器的完全主机名。</li><li>日期与时间：显示当前日期和时间。</li></ul><p>（LCTT 译注：tmux 的状态可以根据需要定制，也会因环境、版本的不同而不同。）</p><h3 id="如何拆分窗口" tabindex="-1">如何拆分窗口 <a class="header-anchor" href="#如何拆分窗口" aria-label="Permalink to “如何拆分窗口”">​</a></h3><p>tmux 允许用户垂直或水平分割窗口，称为窗格。每个窗格都包含自己独立运行的终端实例。我们来看看如何做到这一点。</p><p>按下 <code>Ctrl+b, %</code> 来垂直分割窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-2.png" alt=""></p><p>按下 <code>Ctrl+b, &quot;</code> 来水平分割窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-3.png" alt=""></p><h3 id="如何在窗格之间移动" tabindex="-1">如何在窗格之间移动 <a class="header-anchor" href="#如何在窗格之间移动" aria-label="Permalink to “如何在窗格之间移动”">​</a></h3><p>假设，我们创建了一些窗格，希望在它们之间移动，这该怎么做？如果你不知道怎么做，那么使用 tmux 就没有意义了。使用以下控制键执行操作。在窗格之间移动有许多方法。</p><ul><li>按 <code>Ctrl+b, ←</code> - 选择左边的窗格</li><li>按 <code>Ctrl+b, →</code> - 选择右边的窗格</li><li>按 <code>Ctrl+b, ↑</code> - 选择上边的窗格</li><li>按 <code>Ctrl+b, ↓</code> - 选择下边的窗格</li><li>按 <code>Ctrl+b, {</code> - 来向左交换窗格</li><li>按 <code>Ctrl+b, }</code> - 来向右交换窗格</li><li>按 <code>Ctrl+b, o</code> - 切换到下一个窗格（从左到右，从上到下）</li><li>按 <code>Ctrl+b, ;</code> - 移动到先前活动的窗格</li></ul><p>出于测试目的，我们将在窗格之间移动。现在我们在 <code>pane2</code> 中，它展示了 <code>lsb_release -a</code> 命令的输出。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-4.png" alt=""></p><p>我们将移动到 <code>pane0</code>，它显示 <code>uname -a</code> 命令的输出。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-5.png" alt=""></p><h3 id="如何打开-创建新窗口" tabindex="-1">如何打开/创建新窗口 <a class="header-anchor" href="#如何打开-创建新窗口" aria-label="Permalink to “如何打开/创建新窗口”">​</a></h3><p>你可以在一个终端内打开任意数量的窗口。</p><ul><li>按 <code>Ctrl+b, c</code> 来创建一个新窗口。</li><li>按 <code>Ctrl+b, n</code> 移动到下一个窗口。</li><li>按 <code>Ctrl+b, p</code> 移动到上一个窗口。</li><li>按 <code>Ctrl+b, 0</code> ~ <code>Ctrl+b, 9</code> 立即移动到特定窗口。</li><li>按 <code>Ctrl+b, l</code> 移动到先前选择的窗口。</li></ul><p>我有两个窗口，第一个窗口有三个窗格，其中包含操作系统版本信息，<code>top</code> 命令输出和内核信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-8.png" alt=""></p><p>第二个窗口有两个窗格，其中包含 Linux 发行版 logo 信息。使用以下命令执行操作：</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-6.png" alt=""></p><p>按 <code>Ctrl+b, w</code> 以交互方式选择当前窗口。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-7.png" alt=""></p><h3 id="如何缩放窗格" tabindex="-1">如何缩放窗格 <a class="header-anchor" href="#如何缩放窗格" aria-label="Permalink to “如何缩放窗格”">​</a></h3><p>你正在一些非常小的窗格中工作，并且你希望将其缩小以进行进一步的工作。要做到这一点，使用以下键绑定。</p><p>目前我们有三个窗格，我在 <code>pane1</code> 工作，它使用 <code>top</code> 命令显示系统活动信息，我将缩放它。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-8.png" alt=""></p><p>缩放窗格时，它将隐藏所有其它窗格，并只显示窗口中的缩放窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-9.png" alt=""></p><p>按 <code>Ctrl+b, z</code> 缩放窗格，并再次按下它使缩放窗格恢复原状。</p><h3 id="显示窗格信息" tabindex="-1">显示窗格信息 <a class="header-anchor" href="#显示窗格信息" aria-label="Permalink to “显示窗格信息”">​</a></h3><p>要了解窗格编号及其大小，运行以下命令。</p><p>按 <code>Ctrl+b, q</code> 可简单显示窗格索引。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-10.png" alt=""></p><h3 id="显示窗口信息" tabindex="-1">显示窗口信息 <a class="header-anchor" href="#显示窗口信息" aria-label="Permalink to “显示窗口信息”">​</a></h3><p>要知道窗口编号、布局大小，与窗口关联的窗格数量及其大小等，运行以下命令。</p><p>只需运行 <code>tmux list-windows</code> 即可查看窗口信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-14.png" alt=""></p><h3 id="如何调整窗格大小" tabindex="-1">如何调整窗格大小 <a class="header-anchor" href="#如何调整窗格大小" aria-label="Permalink to “如何调整窗格大小”">​</a></h3><p>你可能需要调整窗格大小来满足你的要求。你必须按下 <code>Ctrl+b, :</code>，然后在页面底部的黄色颜色条上输入以下详细信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-11.png" alt=""></p><p>在上一部分中，我们打印了窗格索引，它同时也显示了窗格大小。为了测试，我们要向增加 <code>10</code> 个单元。参考以下输出，该窗格将 pane1 和 pane2 的大小从 <code>55x21</code> 增加到 <code>55x31</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-13.png" alt=""></p><p><strong>语法：</strong> <code>Ctrl+b, :</code> 然后输入 <code>resize-pane [options] [cells size]</code></p><ul><li><code>Ctrl+b, :</code> 然后输入 <code>resize-pane -D 10</code> 将当前窗格大小向下调整 10 个单元。</li><li><code>Ctrl+b, :</code> 然后输入 <code>resize-pane -U 10</code> 将当前窗格大小向上调整 10 个单元。</li><li><code>Ctrl+b, :</code> 然后输入 <code>resize-pane -L 10</code> 将当前窗格大小向左调整 10 个单元。</li><li><code>Ctrl+b, :</code> 然后输入 <code>resize-pane -R 10</code> 将当前窗格大小向右调整 10 个单元。</li></ul><h3 id="分离并重新连接-tmux-会话" tabindex="-1">分离并重新连接 tmux 会话 <a class="header-anchor" href="#分离并重新连接-tmux-会话" aria-label="Permalink to “分离并重新连接 tmux 会话”">​</a></h3><p>tmux 最强大的功能之一是能够在需要时分离和重新连接会话。</p><p>运行一个长时间运行的进程，然后按下 <code>Ctrl+b</code>，接着按 <code>d</code>，通过离开正在运行的进程安全地分离你的 tmux 会话。</p>',56)),l("p",null,[e[20]||(e[20]=l("strong",null,"建议阅读：",-1)),e[21]||(e[21]=t()),i(a,{href:"https://www.2daygeek.com/how-to-keep-a-process-command-running-after-disconnecting-ssh-session/"},{default:s(()=>[...e[19]||(e[19]=[t("如何在断开 SSH 会话后保持进程/命令继续运行",-1)])]),_:1})]),e[43]||(e[43]=o(`<p>现在，运行一个长时间运行的进程。出于演示目的，我们将把此服务器备份移动到另一个远程服务器以进行灾难恢复（DR）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -avzhe ssh /backup root@192.168.0.161:/backups/week-1/</span></span></code></pre></div><p>在分离 tmux 会话之后，你将获得类似下面的输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[detached (from session 0)]</span></span></code></pre></div><p>运行以下命令以列出可用的 tmux 会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux ls</span></span>
<span class="line"><span>0: 3 windows (created Tue Jan 30 06:17:47 2018) [109x45]</span></span></code></pre></div><p>现在，使用适当的会话 ID 重新连接 tmux 会话，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux attach -t 0</span></span></code></pre></div><h3 id="如何关闭窗格和窗口" tabindex="-1">如何关闭窗格和窗口 <a class="header-anchor" href="#如何关闭窗格和窗口" aria-label="Permalink to “如何关闭窗格和窗口”">​</a></h3><p>只需在相应的窗格中输入 <code>exit</code> 或按下 <code>Ctrl-d</code> 即可关闭它，和终端关闭类似。要关闭窗口，按下 <code>Ctrl+b, &amp;</code>。</p><p>好了，就到这里了，希望你喜欢上它。</p><hr>`,12)),l("p",null,[e[23]||(e[23]=t("via: ",-1)),i(a,{href:"https://www.2daygeek.com/tmux-a-powerful-terminal-multiplexer-emulator-for-linux/"},{default:s(()=>[...e[22]||(e[22]=[t("https://www.2daygeek.com/tmux-a-powerful-terminal-multiplexer-emulator-for-linux/",-1)])]),_:1})]),l("p",null,[e[27]||(e[27]=t("作者：",-1)),i(a,{href:"https://www.2daygeek.com/author/magesh/"},{default:s(()=>[...e[24]||(e[24]=[t("Magesh Maruthamuthu",-1)])]),_:1}),e[28]||(e[28]=t(" 译者：",-1)),i(a,{href:"https://github.com/MjSeven"},{default:s(()=>[...e[25]||(e[25]=[t("MjSeven",-1)])]),_:1}),e[29]||(e[29]=t(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[26]||(e[26]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[32]||(e[32]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[30]||(e[30]=[t("LCTT",-1)])]),_:1}),e[33]||(e[33]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...e[31]||(e[31]=[t("Linux中国",-1)])]),_:1}),e[34]||(e[34]=t(" 荣誉推出",-1))])])}const C=n(u,[["render",m]]);export{w as __pageData,C as default};
